    const name = (i) => ((Lv[i] && Lv[i].name) || ["minutes", "hours", "day", "cycle", "sequence"][i]).toUpperCase();
    const pl = (v, one, many) => `${v} ${+v === 1 ? one : many} per pixel`;
    const res = spp >= DAY * 0.75 ? pl((spp / DAY).toFixed(spp >= 1.5 * DAY ? 0 : 1).replace(/\.0$/, ""), "day", "days") : spp >= 3600 ? `${(spp / 3600).toFixed(1)} h per pixel`
      : spp >= 60 ? `${(spp / 60).toFixed(1)} min per pixel` : spp >= 1 ? `${spp.toFixed(1)} s per pixel`
      : spp * 100 >= 1 ? `${(spp * 100).toFixed(1)} samples per pixel` : `1 sample per ${(1 / (spp * 100)).toFixed(1)} pixels`;
    const ws = S.w.map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]);
    const fade = ws[1][0] > 0.04 ? ` <span class="fade">· fading ${ws[1][1] < ws[0][1] ? "in" : "to"} ${name(ws[1][1])} ${Math.round(ws[1][0] * 100)}%</span>` : "";
