      sched.pass({ src, M: S.M, t: S.cursor, rate: clockRate(), minMag, sel: selection(), engine, enabled: S.w[4] < 0.5,
                   panOf: (k) => MAP.panOf(E.lon[k], E.lat[k]), frameOf: (k) => SvkCook.listenerFrame(LP, E.lat[k], E.lon[k], E.depth_km[k], HD) });
      if (sched.lastBatch.length) { recent.ks = recent.ks.concat(sched.lastBatch).slice(-60); recent.until = performance.now() + 600; }
